const end = Date.now()+Math.max(0, game.secondsLeft()*1000-150);
while (Date.now()<end && game.secondsLeft()>0) {
  if (game.summary().status==="won" || game.summary().status==="lost") { game.nextBoard(); continue; }
  let v=game.view(), R=game.rows, C=game.cols, moved=true;
  if (v.every(row=>row.every(x=>x==="#"))) game.reveal(Math.floor(R/2),Math.floor(C/2));
  while (moved && Date.now()<end && game.secondsLeft()>0) {
    moved=false; v=game.view();
    for(let r=0;r<R;r++) for(let c=0;c<C;c++) if(/^\d$/.test(v[r][c])) {
      let ns=game.neighbors(r,c), hid=[], fl=0;
      for(const [a,b] of ns){ if(v[a][b]==="#") hid.push([a,b]); else if(v[a][b]==="F") fl++; }
      let n=+v[r][c];
      if(hid.length && n-fl===0){ for(const [a,b] of hid){let q=game.reveal(a,b); moved=true; if(q.status==="lost") break;} }
      else if(hid.length && n-fl===hid.length){ for(const [a,b] of hid){if(game.view()[a][b]==="#"){game.toggleFlag(a,b);moved=true;}}}
    }
    let s=game.summary().status; if(s==="won"||s==="lost") break;
  }
  let s=game.summary().status; if(s==="won"||s==="lost"){game.nextBoard();continue;}
  v=game.view(); let pick=null, best=1e9;
  for(let r=0;r<R;r++) for(let c=0;c<C;c++) if(v[r][c]==="#"){let k=0; for(const [a,b] of game.neighbors(r,c)) if(/^\d$/.test(v[a][b])) k++; if(k<best){best=k;pick=[r,c];}}
  if(pick) game.reveal(pick[0],pick[1]);
}
return {boardsSolved:game.boardsSolved(),secondsLeft:game.secondsLeft()};
